import{_ as o,o as t,c as i,a3 as a}from"./chunks/framework.DjfA6S92.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"Collection/sprite.md","filePath":"Collection/sprite.md"}'),l={name:"Collection/sprite.md"};function r(s,e,c,d,p,n){return t(),i("div",null,[...e[0]||(e[0]=[a('<h2 id="q-sprite-雪碧图-知道吗-svg雪碧图了解吗" tabindex="-1">Q: sprite（雪碧图）知道吗？svg雪碧图了解吗？ <a class="header-anchor" href="#q-sprite-雪碧图-知道吗-svg雪碧图了解吗" aria-label="Permalink to &quot;Q: sprite（雪碧图）知道吗？svg雪碧图了解吗？&quot;">​</a></h2><h2 id="a" tabindex="-1">A: <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A:&quot;">​</a></h2><h4 id="雪碧图" tabindex="-1">雪碧图 <a class="header-anchor" href="#雪碧图" aria-label="Permalink to &quot;雪碧图&quot;">​</a></h4><p>概念：将多个小图片拼接到一个图片中。通过background-position和元素尺寸调节需要显示的背景图案。</p><p>优点：</p><ol><li>减少HTTP请求数，极大地提高页面加载速度。</li><li>增加图片信息重复度，提高压缩比，减少图片大小。</li><li>更换风格方便，只需在一张或几张图片上修改颜色或样式即可实现。</li></ol><p>缺点：</p><ol><li>图片合并麻烦。</li><li>维护麻烦，修改一个图片可能需要从新布局整个图片，样式。</li></ol><p>实现方法：</p><ol><li>使用生成器将多张图片打包成一张雪碧图，并为其生成合适的 CSS。</li><li>每张图片都有相应的 CSS 类，该类定义了<code>background-image</code>、<code>background-position</code>和<code>background-size</code>属性。</li><li>使用图片时，将相应的类添加到你的元素中。</li></ol><p>好处：</p><ul><li>减少加载多张图片的 HTTP 请求数（一张雪碧图只需要一个请求）。但是对于 HTTP2 而言，加载多张图片不再是问题。</li><li>提前加载资源，防止在需要时才在开始下载引发的问题，比如只出现在<code>:hover</code>伪类中的图片，不会出现闪烁。</li></ul><p>参考</p><ul><li><a href="https://css-tricks.com/css-sprites/" target="_blank" rel="noreferrer">https://css-tricks.com/css-sprites/</a></li></ul><h4 id="svg-雪碧图" tabindex="-1">SVG 雪碧图 <a class="header-anchor" href="#svg-雪碧图" aria-label="Permalink to &quot;SVG 雪碧图&quot;">​</a></h4><p>01，原理和普通图片雪碧图一样。</p><p>02，好处是不再需要为高清屏准备额外的2倍图。因为SVG与分辨率无关。</p><p>03，实现方式：</p><p>​ 方式1：所有的图标使用<code>&lt;symbol&gt;</code>元素来定义在 SVG 代码中，并且隐藏它。然后使用<code>&lt;use&gt;</code>元素来通过<code>&lt;symbol&gt;</code> 的 <code>xlink:href=&quot;#id&quot;</code>来引用它。</p><p>​ 方式2：用SVG的<code>viewbox</code>属性来指定显示SVG画布的区域，跟<code>background-position</code>原理差不多。</p>',20)])])}const _=o(l,[["render",r]]);export{u as __pageData,_ as default};
